import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();

        double min = 1e15;
        long a2 = 0, b2 = 0;

        for (long b = 1; b <= n; b++) {
            long a = (x * b) / y;

            if (a > 0 && (x * b - (a - 1) * y) == 0) {
                System.out.println((a - 1) + "/" + b);
                return;
            }
            if (x * b - a * y == 0) {
                System.out.println(a + "/" + b);
                return;
            }
            if (x * b - (a + 1) * y == 0) {
                System.out.println((a + 1) + "/" + b);
                return;
            }

            double diff1 = Math.abs(x * b - (a - 1) * y) / ((double) y * b);
            if (a > 0 && diff1 < min) {
                a2 = a - 1;
                b2 = b;
                min = diff1;
            }

            double diff2 = Math.abs(x * b - a * y) / ((double) y * b);
            if (diff2 < min) {
                a2 = a;
                b2 = b;
                min = diff2;
            }

            double diff3 = Math.abs(x * b - (a + 1) * y) / ((double) y * b);
            if (diff3 < min) {
                a2 = a + 1;
                b2 = b;
                min = diff3;
            }
        }
        System.out.println(a2 + "/" + b2);
    }
}
